P.moduleStatus=function(cat){const m=X.modules.find(x=>x.id===cat),a=this.player,level=a.modules?.[cat]||0;if(!m)return {ok:false,text:'未知配件。'};const cost=Object.fromEntries(Object.entries(m.cost).map(([k,n])=>[k,n*(level===1?2:4)]));cost.core=level;return {ok:level>0&&level<3&&!this.s.work&&this.materialStatus(cost).every(x=>!x.missing),level,cost,text:!level?'需先取得並安裝配件':level===3?'已達最高階':this.s.work?'先完成目前工作':'升級需要材料與工時'};};
